#include <iostream>
#include <string>
#include <sstream>
#include <cstdlib>
#include <numeric>

class Rational {
private:
    int numerator;
    int denominator;

    static int gcd(int n, int d) {
        int n1 = std::abs(n);
        int n2 = std::abs(d);
        int result = 1;
        for (int k = 1; k <= n1 && k <= n2; ++k) {
            if (n1 % k == 0 && n2 % k == 0) {
                result = k;
            }
        }
        return result;
    }

public:
    Rational() : numerator(0), denominator(1) {}

    Rational(int num, int den) {
        int factor = gcd(num, den);
        numerator = ((den > 0) ? 1 : -1) * num / factor;
        denominator = std::abs(den) / factor;
    }

    int getNumerator() const { return numerator; }
    int getDenominator() const { return denominator; }

    Rational add(const Rational& second) const {
        int n = numerator * second.denominator + denominator * second.numerator;
        int d = denominator * second.denominator;
        return Rational(n, d);
    }

    Rational subtract(const Rational& second) const {
        int n = numerator * second.denominator - denominator * second.numerator;
        int d = denominator * second.denominator;
        return Rational(n, d);
    }

    Rational multiply(const Rational& second) const {
        int n = numerator * second.numerator;
        int d = denominator * second.denominator;
        return Rational(n, d);
    }

    Rational divide(const Rational& second) const {
        int n = numerator * second.denominator;
        int d = denominator * second.numerator;
        return Rational(n, d);
    }

    int compareTo(const Rational& second) const {
        Rational temp = subtract(second);
        if (temp.getNumerator() < 0) return -1;
        if (temp.getNumerator() == 0) return 0;
        return 1;
    }

    bool equals(const Rational& second) const {
        return compareTo(second) == 0;
    }

    int intValue() const {
        return numerator / denominator;
    }

    double doubleValue() const {
        return 1.0 * numerator / denominator;
    }

    std::string toString() const {
        std::stringstream ss;
        ss << numerator;
        if (denominator > 1) {
            ss << "/" << denominator;
        }
        return ss.str();
    }
};

int main() {
    Rational r1(4, 2);
    Rational r2(2, 3);

    std::cout << r1.toString() << " + " << r2.toString() << " = "
              << r1.add(r2).toString() << "\n";
    std::cout << r1.toString() << " - " << r2.toString() << " = "
              << r1.subtract(r2).toString() << "\n";
    std::cout << r1.toString() << " * " << r2.toString() << " = "
              << r1.multiply(r2).toString() << "\n";
    std::cout << r1.toString() << " / " << r2.toString() << " = "
              << r1.divide(r2).toString() << "\n";

    std::cout << "r2.intValue() is " << r2.intValue() << "\n";
    std::cout << "r2.doubleValue() is " << r2.doubleValue() << "\n";
    std::cout << "r1.compareTo(r2) is " << r1.compareTo(r2) << "\n";
    std::cout << "r1.equals(r1) is " << (r1.equals(r1) ? "true" : "false") << "\n";
    std::cout << "r1.equals(r2) is " << (r1.equals(r2) ? "true" : "false") << "\n";

    return 0;
}

#include <iostream>
#include <cstdlib>

class Rational {
private:
    int numerator;
    int denominator;

    static int gcd(int n, int d) {
        int n1 = std::abs(n);
        int n2 = std::abs(d);
        int g = 1;
        for (int k = 1; k <= n1 && k <= n2; ++k) {
            if (n1 % k == 0 && n2 % k == 0) g = k;
        }
        return g;
    }

public:
    Rational(int num = 0, int den = 1) {
        int factor = gcd(num, den);
        numerator = ((den > 0) ? 1 : -1) * num / factor;
        denominator = std::abs(den) / factor;
    }

    int compareTo(const Rational& second) const {
        int diff = numerator * second.denominator - denominator * second.numerator;
        if (diff < 0) return -1;
        if (diff == 0) return 0;
        return 1;
    }

    // Overloaded < operator function
    bool operator<(const Rational& secondRational) const {
        return compareTo(secondRational) < 0;
    }
};

int main() {
    Rational r1(4, 2); // 2/1
    Rational r2(2, 3); // 2/3

    // Explicit call vs Infix operator invocation
    std::cout << "r1.operator<(r2) is " << (r1.operator<(r2) ? "true" : "false") << "\n";
    std::cout << "r1 < r2 is " << (r1 < r2 ? "true" : "false") << "\n";
    std::cout << "r2 < r1 is " << (r2 < r1 ? "true" : "false") << "\n";

    return 0;
}
